import json, os, urllib.request
key = ''
for p in ('/root/.n8n_env', '/root/Iryna_Karmazina/.env', '/root/unitex-finrep/.env'):
    if os.path.exists(p):
        for ln in open(p):
            if 'N8N_API_KEY' in ln and '=' in ln:
                key = ln.split('=', 1)[1].strip().strip('"')
    if key: break
if not key:
    print('ключ не знайдено'); raise SystemExit
base = 'https://irynakarmazina.app.n8n.cloud/api/v1'
def api(path):
